sessionStart.powershell:
# axis: Auto-sync + load memory at session start
if (Get-Command axis -ErrorAction SilentlyContinue) { axis sync --quiet 2>$null }

$atlasDir = '.ai/memory'
$memory = "$atlasDir/MEMORY.md"
$userMd = "$atlasDir/USER.md"
$today = Get-Date -Format 'yyyy-MM-dd'
$daily = "$atlasDir/daily/$today.md"

if (Test-Path $memory) { Get-Content $memory -Raw }
if (Test-Path $userMd) { Get-Content $userMd -Raw }
if (Test-Path $daily) { Get-Content $daily -Raw }
